from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import combinations


def _route(data, minimum_duration, exact):
    required = data.get("required", [])
    bit = {name: 1 << i for i, name in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    limit = data["coupons"]
    start_state = (data["source"], initial_mask, 0)
    distance = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distance.get(state) != time:
            continue
        if node == data["target"] and mask == full and (not exact or used == limit):
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            duration = edge["duration"]
            choices = [(duration, used)]
            if used < limit:
                discounted = max(minimum_duration,
                                 duration - edge.get("discount", 0))
                choices.append((discounted, used + 1))
            for travel, next_used in choices:
                arrival = depart + travel
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < distance.get(next_state, float("inf")):
                    distance[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator):
        if half_up:
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names_desc = sorted(packages, reverse=True)
    best = None
    best_vector = None

    def cyclic(chosen):
        graph = {}
        for name, version in chosen.items():
            row = next(row for row in packages[name] if row["version"] == version)
            graph[name] = [dep["name"] for dep in row.get("deps", [])
                           if (not dep.get("feature") or dep["feature"] in features)]
        visiting, done = set(), set()

        def visit(name):
            if name in visiting:
                return False
            if name in done:
                return True
            visiting.add(name)
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            visiting.remove(name)
            done.add(name)
            return True

        return not all(visit(name) for name in graph)

    def search(chosen, pending):
        nonlocal best, best_vector
        if not pending:
            if cyclic(chosen):
                return
            vector = tuple(chosen.get(name, -1) for name in names_desc)
            if best_vector is None or vector > best_vector:
                best, best_vector = chosen, vector
            return

        name, low, high = pending[-1]
        rest = pending[:-1]
        if name in chosen:
            version = chosen[name]
            if low <= version <= high:
                search(chosen, rest)
            return

        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in sorted(rows, key=lambda item: item["version"], reverse=True):
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_pending = list(rest)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if not feature or feature in features:
                    next_pending.append((dep["name"], dep["min"], dep["max"]))
            search(next_chosen, next_pending)

    roots = [(name, bounds[0], bounds[1])
             for name, bounds in data["roots"].items()]
    search({}, roots)
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        valid = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        selected = tuple(sorted(ids))
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


SOLVERS = {
    "component_01": lambda data: _route(data, 2, True),
    "component_02": lambda data: _route(data, 1, False),
    "component_03": lambda data: _route(data, 1, True),
    "component_04": lambda data: _route(data, 2, False),
    "component_05": lambda data: _route(data, 2, True),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _intervals,
}
